"""Turn one rule into concrete occurrences (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass
from functools import lru_cache
from math import gcd

from .errors import PlanError

SECONDS_PER_DAY = 86400
MONTHS_PER_GREGORIAN_CYCLE = 4800
LAST_DAY = dt.date.max.toordinal()
UTC = dt.timezone.utc
UTC_ORIGIN = dt.datetime(1, 1, 1, tzinfo=UTC)


@dataclass
class Occurrence:
    rule: object          # RuleDef
    key: str
    start: int            # UTC seconds since 0001-01-01T00:00
    end: int


def instant(local, zone):
    # fold=0 uses the earlier instant in a fold and the pre-gap offset in a gap.
    offset = local.replace(tzinfo=zone, fold=0).utcoffset()
    wall = (local.toordinal() - 1) * SECONDS_PER_DAY
    wall += local.hour * 3600 + local.minute * 60 + local.second
    return wall - int(offset.total_seconds())


def _utc_datetime(value):
    return UTC_ORIGIN + dt.timedelta(seconds=value)


def _local_datetime(value, zone):
    if 0 <= value < LAST_DAY * SECONDS_PER_DAY:
        return _utc_datetime(value).astimezone(zone)
    # A valid local date at either end of the calendar can cross the UTC year boundary.
    edge = dt.datetime.min if value < 0 else dt.datetime.max.replace(microsecond=0)
    elapsed = value - instant(edge, zone)
    return (edge + dt.timedelta(seconds=elapsed)).replace(tzinfo=zone)


@lru_cache(maxsize=4096)
def _local_day(value, zone):
    try:
        return _local_datetime(value, zone).toordinal()
    except (OverflowError, ValueError):
        return 0 if value < SECONDS_PER_DAY else LAST_DAY + 1


@lru_cache(maxsize=4096)
def timestamp(value, zone):
    # Historical offsets can include seconds. The output format has minute precision.
    return _local_datetime(value, zone).isoformat(timespec="seconds")[:25]


@lru_cache(maxsize=4096)
def _utc_key(value):
    return _utc_datetime(value).isoformat(timespec="minutes")[:16] + "Z"


def _aligned(anchor, stride, lower):
    """First point on the recurrence grid at or after lower."""
    return lower + (anchor - lower) % stride


def _month_index(day):
    return (day.year - 1) * 12 + day.month - 1


def _candidate_days(rule, first, last):
    first = max(first, rule.start)
    if rule.until is not None:
        last = min(last, rule.until)
    if first > last:
        return

    if rule.unit == "month":
        lower = _aligned(_month_index(rule.start), rule.every, _month_index(first))
        cycle_steps = MONTHS_PER_GREGORIAN_CYCLE // gcd(rule.every, MONTHS_PER_GREGORIAN_CYCLE)
        repeat_at = lower + cycle_steps * rule.every
        for month_index in range(lower, _month_index(last) + 1, rule.every):
            if month_index == repeat_at:
                return  # No selected day exists in any of the repeating active months.
            year, month = divmod(month_index, 12)
            year, month = year + 1, month + 1
            month_len = calendar.monthrange(year, month)[1]
            days = {month_len if item == "last" else item for item in rule.on}
            for number in sorted(days):
                if number <= month_len:
                    repeat_at = None
                    day = dt.date(year, month, number)
                    if first <= day <= last:
                        yield day
        return

    lower, upper = first.toordinal(), last.toordinal()
    anchor = rule.start.toordinal()
    if rule.unit == "day":
        for day in range(_aligned(anchor, rule.every, lower), upper + 1, rule.every):
            yield dt.date.fromordinal(day)
    else:
        monday = anchor - rule.start.weekday()
        stride = 7 * rule.every
        first_week = _aligned(monday, stride, lower - first.weekday())
        for week in range(first_week, upper + 1, stride):
            for weekday in rule.on:
                day = week + weekday
                if lower <= day <= upper:
                    yield dt.date.fromordinal(day)


def _calendar_slots(ruledef, first, last):
    if first <= last:
        dates = dt.date.fromordinal(first), dt.date.fromordinal(last)
        for day in _candidate_days(ruledef.rule, *dates):
            position = day.toordinal()
            seen = set()
            for clock in ruledef.rule.at:
                start = instant(dt.datetime.combine(day, clock), ruledef.tz)
                if start not in seen:
                    seen.add(start)
                    yield position, clock, start


def _shifted_slots(ruledef, first, last, block_start, destination):
    pending = set(ruledef.rule.at)
    if destination <= LAST_DAY:
        pending.difference_update(clock for _, clock, _ in _calendar_slots(ruledef, destination, destination))
    if not pending:
        return
    day = dt.date.fromordinal(min(destination, LAST_DAY))
    # Keep a shift past the last supported year addressable by its original key.
    rollover = (destination - day.toordinal()) * SECONDS_PER_DAY
    # Earlier keys in the same holiday range can claim a slot even outside these bounds.
    for position, clock, _ in _calendar_slots(ruledef, block_start, last):
        if clock in pending:
            pending.remove(clock)
            if position >= first:
                yield position, clock, instant(dt.datetime.combine(day, clock), ruledef.tz) + rollover
            if not pending:
                break


def _calendar_candidates(ruledef, holidays, first, last):
    if ruledef.holiday == "keep":
        yield from _calendar_slots(ruledef, first, last)
        return
    first = max(first, ruledef.rule.start.toordinal())
    if ruledef.rule.until is not None:
        last = min(last, ruledef.rule.until.toordinal())
    if first > last:
        return
    for left, right in holidays.between(first, last):
        yield from _calendar_slots(ruledef, first, left - 1)
        if ruledef.holiday == "shift":
            yield from _shifted_slots(ruledef, first, min(last, right), left, right + 1)
        first = right + 1
    yield from _calendar_slots(ruledef, first, last)


def _elapsed_candidates(ruledef, holidays, first, last):
    stride, anchor = ruledef.stride, ruledef.anchor
    start = _aligned(anchor, stride, max(first, anchor))
    until = ruledef.rule.until
    if until is not None:
        # Offsets are less than a day. Check the boundary by local date because clocks can go back.
        until = until.toordinal() * SECONDS_PER_DAY
        last = min(last, until + SECONDS_PER_DAY - 1)
    skip = ruledef.holiday == "skip" and bool(holidays.ranges)
    while start <= last:
        near_until = until is not None and start >= until - SECONDS_PER_DAY
        if skip or near_until:
            day = _local_day(start, ruledef.tz)
            if near_until and (day - 1) * SECONDS_PER_DAY >= until:
                start += stride
                continue
            block = holidays.containing(day) if skip else None
            if block is not None:
                left, right = block
                after = start + stride
                # Inside this part of the range, even the largest offset change stays on a holiday.
                if start >= left * SECONDS_PER_DAY:
                    after = max(after, (right - 1) * SECONDS_PER_DAY)
                start = _aligned(anchor, stride, after)
                continue
        yield start, None, start
        start += stride


def expand(ruledef, holidays, first, last, *, counted=True):
    """Yield (key, start) in key order, bounded by nominal dates or original UTC starts."""
    if first > last:
        return
    limit = ruledef.rule.times if counted else None
    lower = first
    if ruledef.anchor is None:
        candidates = _calendar_candidates
        if limit is not None:
            lower = ruledef.rule.start.toordinal()
    else:
        candidates = _elapsed_candidates
        if limit is not None:
            if ruledef.holiday == "keep" or not holidays.ranges:
                last = min(last, ruledef.anchor + (limit - 1) * ruledef.stride)
                limit = None
            else:
                lower = ruledef.anchor
    for count, (position, clock, start) in enumerate(candidates(ruledef, holidays, lower, last), 1):
        if position >= first:
            if clock is None:
                try:
                    key = _utc_key(position)
                except (ValueError, OverflowError) as exc:
                    raise PlanError(f"rule {ruledef.id}: UTC key is outside the supported calendar") from exc
            else:
                key = f"{dt.date.fromordinal(position).isoformat()}T{clock.isoformat(timespec='minutes')}"
            yield key, start
        if count == limit:
            break


def window_starts(ruledef, holidays, after, before):
    """Find candidates that can start strictly between the given UTC instants."""
    if ruledef.anchor is not None:
        yield from expand(ruledef, holidays, after + 1, before - 1)
        return
    # A nominal local time is less than one day from its UTC instant, even in a gap.
    first = max(1, (after - SECONDS_PER_DAY) // SECONDS_PER_DAY + 1)
    last = min(LAST_DAY, (before + SECONDS_PER_DAY) // SECONDS_PER_DAY + 1)
    if ruledef.holiday == "shift":
        block = holidays.containing(first - 1)
        if block is not None:
            first = block[0]
    for key, start in expand(ruledef, holidays, first, last):
        if after < start < before:
            yield key, start
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import datetime as dt
import heapq
import re

from .errors import PlanError
from .expand import Occurrence, instant, timestamp, window_starts
from .plan import load_plan
from .rules import LOCAL_MINUTE, TIME

BOUND = re.compile(rf"{LOCAL_MINUTE}(?::[0-5][0-9])?(?:Z|[+-]{TIME})")


def _parse_bound(text):
    if isinstance(text, str) and BOUND.fullmatch(text):
        try:
            value = dt.datetime.fromisoformat(text[:-1] + "+00:00" if text.endswith("Z") else text)
        except ValueError:
            pass
        else:
            return instant(value, value.tzinfo)
    raise PlanError(f"invalid date-time {text!r}")


def _collect(plan, start, end):
    for ruledef in plan.rules:
        overrides = plan.overrides.get(ruledef.id, {})
        length = ruledef.rule.minutes * 60
        for key, left in window_starts(ruledef, plan.holidays, start - length, end):
            if key not in overrides:
                yield Occurrence(ruledef, key, left, left + length)
        for key, override in overrides.items():
            left = override.start
            if left is not None:
                right = left + (length if override.minutes is None else override.minutes * 60)
                if left < end and right > start:
                    yield Occurrence(ruledef, key, left, right)


def _query(raw_plan, start, end):
    plan = load_plan(raw_plan)
    lo, hi = _parse_bound(start), _parse_bound(end)
    if lo >= hi:
        raise PlanError("end must be after start")
    return plan, lo, hi


def _as_dict(occ, start, end):
    try:
        left, right = timestamp(start, occ.rule.tz), timestamp(end, occ.rule.tz)
    except (OverflowError, ValueError) as exc:
        raise PlanError(f"rule {occ.rule.id}: timestamp is outside the supported calendar") from exc
    return {"rule": occ.rule.id, "key": occ.key, "start": left, "end": right}


def occurrences(plan, start, end):
    plan, lo, hi = _query(plan, start, end)
    found = sorted(_collect(plan, lo, hi),
                   key=lambda occ: (occ.start, occ.end, -occ.rule.priority, occ.rule.index, occ.key))
    return [_as_dict(occ, occ.start, occ.end) for occ in found]


def _rank(occ):
    return -occ.rule.priority, occ.start, occ.rule.index, occ.key


def _segments(found):
    """Sweep the full intervals and yield each maximal run with the same winner."""
    ordered = sorted(found, key=lambda occ: occ.start)
    edges = sorted({edge for occ in ordered for edge in (occ.start, occ.end)})
    active = []
    next_index = 0
    winner = None
    for edge in edges:
        while next_index < len(ordered) and ordered[next_index].start == edge:
            occ = ordered[next_index]
            heapq.heappush(active, (_rank(occ), occ))
            next_index += 1
        while active and active[0][1].end <= edge:
            heapq.heappop(active)
        next_winner = active[0][1] if active else None
        if next_winner is not winner:
            if winner is not None:
                yield winner, segment_start, edge
            winner, segment_start = next_winner, edge


def agenda(plan, start, end):
    plan, lo, hi = _query(plan, start, end)
    minimum = plan.min_segment * 60
    rows = []
    for occ, left, right in _segments(_collect(plan, lo, hi)):
        if (left != occ.start or right != occ.end) and right - left < minimum:
            continue
        left, right = max(left, lo), min(right, hi)
        if left < right:
            rows.append(_as_dict(occ, left, right))
    return rows
import json
import sys
from decimal import Decimal

from .errors import PlanError, RuleSyntaxError
from .query import agenda, occurrences
from .rules import canonical


def _invalid_json_constant(word):
    raise ValueError(f"invalid JSON constant {word}")


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    try:
        if len(argv) == 2 and argv[0] == "canonical":
            print(canonical(argv[1]))
            return 0
        if len(argv) != 4 or argv[0] not in ("occurrences", "agenda"):
            print("usage: python3 -m cadence {occurrences,agenda} START END PLAN.json", file=sys.stderr)
            print("       python3 -m cadence canonical RULE", file=sys.stderr)
            return 1
        command, start, end, path = argv
        try:
            with open(path, "rb") as f:
                raw = f.read()
            # The JSON bytes decoder permits malformed Unicode surrogate sequences.
            text = raw.decode(json.detect_encoding(raw))
            plan = json.loads(text, parse_int=lambda word: int(Decimal(word)),
                              parse_constant=_invalid_json_constant)
        except (OSError, ValueError, RecursionError) as exc:
            print(f"error: {exc}", file=sys.stderr)
            return 1
        query = occurrences if command == "occurrences" else agenda
        rows = query(plan, start, end)
        if rows:
            for row in rows:
                print(row["start"], row["end"], row["rule"], row["key"])
        else:
            print("nothing scheduled")
        return 0
    except PlanError as exc:
        print(f"error: {exc}", file=sys.stderr)
        if isinstance(exc, RuleSyntaxError):
            print(exc.text, file=sys.stderr)
            print(" " * exc.position + "^", file=sys.stderr)
        return 2

"""Rule text parsing (SPEC.md section 2)."""

import datetime as dt
import re
from dataclasses import dataclass, field
from decimal import Decimal

from .errors import PlanError, RuleSyntaxError

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
ELAPSED_UNITS = {"minute": 60, "hour": 3600}
UNITS = {form: unit for unit in ("day", "week", "month", *ELAPSED_UNITS) for form in (unit, unit + "s")}

POSITIVE = r"[1-9][0-9]*"
DATE = r"[0-9]{4}-[0-9]{2}-[0-9]{2}"
TIME = r"(?:[01][0-9]|2[0-3]):[0-5][0-9]"
LOCAL_MINUTE = rf"{DATE}T{TIME}"
DURATION = re.compile(rf"(?:({POSITIVE})d)?(?:({POSITIVE})h)?(?:({POSITIVE})m)?")


@dataclass
class Rule:
    every: int = 1
    unit: str = "day"
    on: list = field(default_factory=list)   # weekday indexes, or month days / "last"
    at: list = field(default_factory=list)   # datetime.time
    minutes: int = 0
    start: dt.date = None
    local_anchor: dt.datetime = None        # minute and hour rules
    until: dt.date = None
    times: int = None


def _positive(word):
    if re.fullmatch(POSITIVE, word):
        # The grammar puts no digit limit on counts or duration parts.
        return int(Decimal(word))


def parse_duration(word):
    """Return the number of minutes, or None for an invalid duration."""
    if not isinstance(word, str) or not word:
        return None
    match = DURATION.fullmatch(word.lower())
    if match:
        return sum(int(Decimal(part)) * scale
                   for part, scale in zip(match.groups(), (1440, 60, 1)) if part)


def format_duration(minutes):
    days, remainder = divmod(minutes, 1440)
    hours, minutes = divmod(remainder, 60)
    return "".join(f"{Decimal(value)}{unit}" for value, unit in
                   ((days, "d"), (hours, "h"), (minutes, "m")) if value)


def _date(word):
    if re.fullmatch(DATE, word):
        return dt.date.fromisoformat(word)


def _time(word):
    if re.fullmatch(TIME, word):
        return dt.time.fromisoformat(word)


def _local_minute(word):
    if re.fullmatch(LOCAL_MINUTE, word.upper()):
        return dt.datetime.fromisoformat(word)


def _month_day(word):
    if word == "last":
        return word
    if re.fullmatch(r"[1-9]|[12][0-9]|3[01]", word):
        return int(word)


def _list(word, parse_item):
    items = [parse_item(item) for item in word.split(",")]
    if None not in items and len(set(items)) == len(items):
        return items


class _Words:
    def __init__(self, text):
        self.text = text
        self.words = list(re.finditer(r"[^ \t]+", text))
        self.index = 0

    def peek(self):
        if self.index < len(self.words):
            return self.words[self.index].group().lower()

    def error(self, message):
        position = self.words[self.index].start() if self.index < len(self.words) else len(self.text)
        return RuleSyntaxError(message, position, self.text)

    def accept(self, keyword):
        if self.peek() == keyword:
            self.index += 1
            return True
        return False

    def expect(self, keyword):
        if not self.accept(keyword):
            raise self.error(f"expected '{keyword}'")

    def convert(self, what, parse):
        word = self.peek()
        if word is None:
            raise self.error(f"expected {what}, found end of rule")
        try:
            value = parse(word)
        except (ValueError, KeyError):
            value = None
        if value is None:
            raise self.error(f"expected {what}, found {self.words[self.index].group()!r}")
        self.index += 1
        return value


def parse_rule(text):
    if not isinstance(text, str):
        raise PlanError("rule text must be a string")
    w = _Words(text)
    rule = Rule()
    w.expect("every")
    if w.peek() and w.peek()[0] in "0123456789":
        rule.every = w.convert("a positive count", _positive)
    rule.unit = w.convert("a unit", UNITS.__getitem__)
    elapsed = rule.unit in ELAPSED_UNITS
    if not elapsed:
        if rule.unit != "day" and w.accept("on"):
            if rule.unit == "month":
                days = w.convert("month days", lambda s: _list(s, _month_day))
                rule.on = sorted(days, key=lambda day: 32 if day == "last" else day)
            else:
                days = w.convert("weekdays", lambda s: _list(s, WEEKDAYS.index))
                rule.on = sorted(days)
        w.expect("at")
        rule.at = sorted(w.convert("times", lambda s: _list(s, _time)))
    w.expect("for")
    rule.minutes = w.convert("a duration", parse_duration)
    w.expect("from")
    if elapsed:
        rule.local_anchor = w.convert("a local date-time", _local_minute)
        rule.start = rule.local_anchor.date()
    else:
        rule.start = w.convert("a date", _date)
    if w.accept("until"):
        def until_date(word):
            date = _date(word)
            if date is not None and date >= rule.start:
                return date

        rule.until = w.convert("a date on or after 'from'", until_date)
    elif w.accept("times"):
        rule.times = w.convert("a positive count", _positive)
    if w.peek() is not None:
        raise w.error("unexpected token after rule")
    if not rule.on:
        if rule.unit == "week":
            rule.on = [rule.start.weekday()]
        elif rule.unit == "month":
            rule.on = [rule.start.day]
    return rule


def canonical(text):
    rule = parse_rule(text)
    out = ["every", str(Decimal(rule.every)), rule.unit if rule.every == 1 else rule.unit + "s"]
    if rule.unit == "week":
        out += ["on", ",".join(WEEKDAYS[d] for d in rule.on)]
    elif rule.unit == "month":
        out += ["on", ",".join(str(d) for d in rule.on)]
    if rule.at:
        out += ["at", ",".join(t.isoformat(timespec="minutes") for t in rule.at)]
    out += ["for", format_duration(rule.minutes)]
    anchor = rule.start.isoformat() if rule.local_anchor is None else rule.local_anchor.isoformat(timespec="minutes")
    out += ["from", anchor]
    if rule.until is not None:
        out += ["until", rule.until.isoformat()]
    if rule.times is not None:
        out += ["times", str(Decimal(rule.times))]
    return " ".join(out)
"""Plan loading (SPEC.md sections 1 and 5)."""

import datetime as dt
import re
import zoneinfo
from dataclasses import dataclass
from functools import lru_cache

from .errors import PlanError, RuleSyntaxError
from .expand import UTC, expand, instant
from .holidays import Holidays
from .rules import DATE, ELAPSED_UNITS, LOCAL_MINUTE, Rule, parse_duration, parse_rule


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: zoneinfo.ZoneInfo
    priority: int
    holiday: str
    anchor: int = None        # UTC seconds for minute and hour rules
    stride: int = None


@dataclass
class Override:
    start: int = None        # None for a cancellation
    minutes: int = None


@dataclass
class Plan:
    rules: list
    overrides: dict          # rule id -> key -> Override
    min_segment: int
    holidays: Holidays


@lru_cache(maxsize=1)
def _iana_names(_search_path):
    # Cache by TZPATH so reset_tzpath() takes effect on the next query.
    return zoneinfo.available_timezones() - {"localtime", "posixrules"}


def _zone(name, label):
    if isinstance(name, str) and name in _iana_names(zoneinfo.TZPATH):
        try:
            return zoneinfo.ZoneInfo(name)
        except (ValueError, zoneinfo.ZoneInfoNotFoundError, OSError):
            pass
    raise PlanError(f"{label}: invalid timezone {name!r}")


def _duration(word, label):
    minutes = parse_duration(word)
    if minutes is None:
        raise PlanError(f"{label}: invalid duration {word!r}")
    return minutes


def _load_rules(raw, default_tz):
    if not isinstance(raw, list):
        raise PlanError("rules must be a list")
    rules = {}
    for index, item in enumerate(raw):
        if not isinstance(item, dict):
            raise PlanError(f"rule #{index}: expected an object")
        rid = item.get("id")
        if not isinstance(rid, str) or not re.fullmatch(r"[A-Za-z0-9_-]+", rid):
            raise PlanError(f"rule #{index}: invalid id {rid!r}")
        if rid in rules:
            raise PlanError(f"rule {rid}: duplicate id")
        text = item.get("rule")
        if not isinstance(text, str):
            raise PlanError(f"rule {rid}: rule text must be a string")
        try:
            rule = parse_rule(text)
        except RuleSyntaxError as exc:
            raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position, text) from exc
        tz = _zone(item["timezone"], f"rule {rid}") if "timezone" in item else default_tz
        priority = item.get("priority", 0)
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise PlanError(f"rule {rid}: priority must be an integer")
        holiday = item.get("holiday", "keep")
        if holiday not in ("keep", "skip", "shift"):
            raise PlanError(f"rule {rid}: invalid holiday policy {holiday!r}")
        anchor = stride = None
        if rule.local_anchor is not None:
            if holiday == "shift":
                raise PlanError(f"rule {rid}: minute and hour rules cannot shift holidays")
            anchor = instant(rule.local_anchor, tz)
            stride = rule.every * ELAPSED_UNITS[rule.unit]
        rules[rid] = RuleDef(index, rid, rule, tz, priority, holiday, anchor, stride)
    return rules


def _override_key(ruledef, holidays, key):
    if isinstance(key, str):
        if len(ruledef.rule.at) == 1 and re.fullmatch(DATE, key):
            time = ruledef.rule.at[0].isoformat(timespec="minutes")
            key = f"{key}T{time}"
        elapsed = ruledef.anchor is not None
        if re.fullmatch(LOCAL_MINUTE + "Z" if elapsed else LOCAL_MINUTE, key):
            try:
                if elapsed:
                    minute = dt.datetime.fromisoformat(key[:-1])
                    # Historical offsets may put the grid between exact UTC minutes.
                    position = instant(minute, UTC) + ruledef.anchor % 60
                else:
                    position = dt.date.fromisoformat(key[:10]).toordinal()
            except ValueError:
                pass
            else:
                candidates = expand(ruledef, holidays, position, position, counted=False)
                if any(candidate == key for candidate, _ in candidates):
                    return key, position
    raise PlanError(f"rule {ruledef.id}: invalid override key {key!r}")


def _move_start(ruledef, text):
    if isinstance(text, str) and re.fullmatch(LOCAL_MINUTE, text):
        try:
            local = dt.datetime.fromisoformat(text)
        except ValueError:
            pass
        else:
            return instant(local, ruledef.tz)
    raise PlanError(f"rule {ruledef.id}: move override needs a valid 'to'")


def _load_overrides(raw, rules, holidays):
    if not isinstance(raw, list):
        raise PlanError("overrides must be a list")
    overrides = {}
    counted_keys = {}
    for item in raw:
        if not isinstance(item, dict):
            raise PlanError("override must be an object")
        rid = item.get("rule")
        if not isinstance(rid, str) or rid not in rules:
            raise PlanError(f"override for unknown rule {rid!r}")
        ruledef = rules[rid]
        key, position = _override_key(ruledef, holidays, item.get("key"))
        by_key = overrides.setdefault(rid, {})
        if key in by_key:
            raise PlanError(f"rule {rid}: duplicate override for {key}")
        action = item.get("action")
        if action == "cancel":
            by_key[key] = Override()
        elif action == "move":
            start = _move_start(ruledef, item.get("to"))
            minutes = _duration(item["for"], f"rule {rid}: move override") if "for" in item else None
            by_key[key] = Override(start, minutes)
        else:
            raise PlanError(f"rule {rid}: unknown override action {action!r}")
        if ruledef.rule.times is not None:
            counted_keys.setdefault(rid, {})[key] = position

    for rid, positions in counted_keys.items():
        pending = set(positions)
        first, last = min(positions.values()), max(positions.values())
        for key, _ in expand(rules[rid], holidays, first, last):
            pending.discard(key)
            if not pending:
                break
        if pending:
            raise PlanError(f"rule {rid}: override key {min(pending)} is past the 'times' limit")
    return overrides


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"], "plan")
    holidays = Holidays(raw.get("holidays", []))
    rules = _load_rules(raw.get("rules"), default_tz)
    overrides = _load_overrides(raw.get("overrides", []), rules, holidays)
    min_segment = _duration(raw["min_segment"], "min_segment") if "min_segment" in raw else 0
    return Plan(list(rules.values()), overrides, min_segment, holidays)
"""Inclusive holiday ranges shared by all rules in a plan."""

import datetime as dt
import re
from bisect import bisect_right

from .errors import PlanError
from .rules import DATE

ENTRY = re.compile(rf"({DATE})(?:\.\.({DATE}))?")


class Holidays:
    def __init__(self, entries):
        if not isinstance(entries, list):
            raise PlanError("holidays must be a list")

        ranges = []
        for entry in entries:
            match = ENTRY.fullmatch(entry) if isinstance(entry, str) else None
            if match:
                try:
                    first = dt.date.fromisoformat(match[1]).toordinal()
                    last = dt.date.fromisoformat(match[2]).toordinal() if match[2] else first
                except ValueError:
                    pass
                else:
                    if first <= last:
                        ranges.append((first, last))
                        continue
            raise PlanError(f"invalid holiday {entry!r}")

        self.ranges = []
        for first, last in sorted(ranges):
            if self.ranges and first <= self.ranges[-1][1] + 1:
                previous, end = self.ranges[-1]
                self.ranges[-1] = previous, max(last, end)
            else:
                self.ranges.append((first, last))
        self.starts = [first for first, _ in self.ranges]

    def containing(self, day):
        index = bisect_right(self.starts, day) - 1
        if index >= 0 and day <= self.ranges[index][1]:
            return self.ranges[index]

    def between(self, first, last):
        """Yield full holiday ranges intersecting the given inclusive bounds."""
        start = max(0, bisect_right(self.starts, first) - 1)
        for index in range(start, len(self.ranges)):
            left, right = self.ranges[index]
            if left > last:
                break
            if right >= first:
                yield left, right
